<div class="portal-native-forms portal-admin-content">
@if($modulePath==='/panel/admin/annual-slogan')
<section x-data="annualSlogan" class="portal-annual-slogan"><p class="portal-admin-help">لوگوی شعار سال مستقل از بنر است و پس از ذخیره در استانداری و تمام فرمانداری‌ها جایگزین می‌شود.</p><div class="portal-slogan-current"><img :src="preview||current" alt="لوگوی شعار سال" class="max-h-64 w-full object-contain"></div><form @submit.prevent="save()"><fieldset :disabled="busy"><label>تصویر جدید شعار سال<input type="file" x-ref="file" accept="image/png,image/jpeg,image/webp" @change="choose($event)" required></label><small>فرمت PNG، JPEG یا WebP؛ اندازهٔ مجاز تابع تنظیمات بارگذاری سامانه است.</small><button class="portal-button" type="submit" :disabled="busy||!file" x-text="busy?'در حال ذخیره…':'ذخیرهٔ شعار سال'">ذخیرهٔ شعار سال</button></fieldset></form><p role="alert" class="portal-auth-error" x-show="error" x-text="error"></p><p role="status" x-show="message" x-text="message"></p></section>
@elseif($modulePath==='/panel/admin/settings')
<section x-data="siteSettings" class="portal-settings"><form @submit.prevent="save()"><fieldset :disabled="busy"><template x-for="entry in entries" :key="entry.key"><label class="block my-5"><strong x-text="entry.label"></strong><input x-model="entry.editing" :type="entry.key==='site.app_url'?'url':'text'" :required="entry.key==='site.name'" maxlength="2048"><template x-if="entry.image"><span><input type="file" accept="image/jpeg,image/png,image/webp" @change="files[entry.key]=$event.target.files[0]"><img x-show="entry.editing" :src="entry.editing||'/design/site/assets/image/logo.png'" :alt="entry.label" class="max-h-32 max-w-full object-contain mt-3"></span></template></label></template><h2>اطلاعات تماس</h2><template x-for="[key,label] in Object.entries(contactLabels)" :key="key"><label><span x-text="label"></span><input x-model="contact[key]" :type="key==='email'?'email':'text'"></label></template><button type="submit" class="portal-button" x-text="busy?'در حال ذخیره…':'ذخیره تنظیمات'">ذخیره تنظیمات</button></fieldset></form><p role="alert" x-text="error"></p><p role="status" x-text="message"></p></section>
@elseif($modulePath==='/panel/admin/account')
<section x-data="accountForm"><form @submit.prevent="saveProfile()"><fieldset :disabled="busy"><label>نام<input x-model="name" required></label><label>ایمیل<input type="email" x-model="email"></label><button class="portal-button">ذخیره مشخصات</button></fieldset></form><form @submit.prevent="savePassword()" class="mt-8"><h2>تغییر رمز عبور</h2><fieldset :disabled="busy"><label>رمز فعلی<input type="password" x-model="current_password" autocomplete="current-password" required></label><label>رمز جدید<input type="password" x-model="password" autocomplete="new-password" minlength="12" required></label><label>تکرار رمز جدید<input type="password" x-model="password_confirmation" autocomplete="new-password" required></label><button class="portal-button">تغییر رمز</button></fieldset></form><p role="alert" x-text="error"></p><p role="status" x-text="message"></p></section>
@elseif($modulePath==='/panel/admin/logout')
<form action="/session/logout" method="post" x-data="apiForm('auth/logout')" @submit.prevent="submit($event).then(()=>{if(!error)location.assign(@js($context['login_path']))})">@csrf<p>برای خروج از حساب مدیریتی دکمه را بزنید.</p><button class="portal-button" :disabled="busy">خروج از مدیریت</button><p role="alert" x-text="error"></p></form>
@elseif($modulePath==='/panel/admin/audit-logs')
<section x-data="auditLog"><form class="portal-admin-toolbar" @submit.prevent="load()"><label>نام عملیات<input x-model="action" maxlength="80" placeholder="contents.updated" dir="ltr"></label><label>شناسهٔ کاربر<input x-model="user_id" type="number" min="1"></label><button class="portal-button" :disabled="busy">فیلتر</button><button type="button" @click="load(page)" :disabled="busy">تازه‌سازی</button></form><div class="portal-admin-table"><table class="education-table"><thead><tr><th>عملیات</th><th>کاربر</th><th>زمان</th><th>رکورد</th><th>تغییرات</th></tr></thead><tbody><template x-for="row in rows" :key="row.id"><tr><td x-text="row.action"></td><td x-text="row.user_id??'سامانه'"></td><td x-text="new Date(row.created_at).toLocaleString('fa-IR')"></td><td x-text="row.subject_id??'—'"></td><td><details><summary>مشاهده</summary><pre dir="ltr" x-text="JSON.stringify(row.changes,null,2)"></pre></details></td></tr></template></tbody></table></div><p x-show="!busy&&!rows.length">رویدادی ثبت نشده است.</p><nav class="portal-admin-pagination" aria-label="صفحه‌های رویدادها" x-show="meta&&meta.last_page>1"><button @click="load(page-1)" :disabled="busy||page<=1">صفحه قبل</button><span x-text="'صفحهٔ '+page+' از '+(meta?.last_page??1)"></span><button @click="load(page+1)" :disabled="busy||page>=(meta?.last_page??1)">صفحه بعد</button></nav><p role="alert" x-text="error"></p></section>
@endif
</div>
